mapper.select:
SELECT EXISTS (
    SELECT 1 FROM patient WHERE id = #{patientId} AND deleted_at IS NULL
)

SELECT EXISTS (
    SELECT 1 FROM patient_user_relation
    WHERE user_id = #{userId}
      AND patient_id = #{patientId}
      AND deleted_at IS NULL
)

SELECT EXISTS (
    SELECT 1
    FROM consult_record
    WHERE patient_id = #{patientId}
      AND doctor_id = #{doctorId}
      AND status IN ('PENDING', 'IN_PROGRESS')
      AND deleted_at IS NULL
)

SELECT cr.id, cr.appointment_id, d.name AS doctor_name, cr.status, cr.updated_at
FROM consult_record cr
LEFT JOIN doctor d ON d.id = cr.doctor_id
WHERE cr.patient_id = #{patientId}
  AND cr.deleted_at IS NULL

    AND cr.status = #{status}

ORDER BY cr.updated_at DESC, cr.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM consult_record
WHERE patient_id = #{patientId}
  AND deleted_at IS NULL

    AND status = #{status}
